import Mage from '@mage-space/sdk';

const mage = new Mage(); // reads MAGE_API_KEY

const request = await mage.generate('mango', {
  prompt: 'Editorial portrait in soft daylight, 35mm film look',
  aspect_ratio: '4:5',
});

console.log(request.request_id, request.status);

import Mage from '@mage-space/sdk';

const mage = new Mage(); // reads MAGE_API_KEY

const { architectures } = await mage.architectures.list();

for (const architecture of architectures) {
  console.log(architecture.id, architecture.gems);
}

import Mage from '@mage-space/sdk';

const mage = new Mage(); // reads MAGE_API_KEY

const request = await mage.requests.get('REQUEST_ID');

// Or poll until it is completed, failed, or cancelled:
const final = await mage.requests.wait('REQUEST_ID');
console.log(final.status, final.result?.url);

import Mage from '@mage-space/sdk';

const mage = new Mage(); // reads MAGE_API_KEY

const request = await mage.requests.cancel('REQUEST_ID');

console.log(request.status); // cancelled

import Mage from '@mage-space/sdk';

const mage = new Mage(); // reads MAGE_API_KEY

const account = await mage.account.get();

console.log(account.gems.balance);

import { readFile } from 'node:fs/promises';
import Mage from '@mage-space/sdk';

const mage = new Mage(); // reads MAGE_API_KEY

// Creates the ticket and uploads the file to it.
const ticket = await mage.uploads.upload(await readFile('clip.mp4'), {
  contentType: 'video/mp4',
});

console.log(ticket.url); // send this in any media field

import Mage from '@mage-space/sdk';

const mage = new Mage(); // reads MAGE_API_KEY

const page = await mage.characters.list({ limit: 50 });

for (const character of page.data) {
  console.log(`@${character.handle}`, character.name);
}
// Pass page.next_cursor as cursor for the next page.

import Mage from '@mage-space/sdk';

const mage = new Mage(); // reads MAGE_API_KEY

await mage.characters.create({
  name: 'Ana',
  handle: 'ana',
  image: 'https://example.com/ana.jpg',
});

await mage.run('mango', { prompt: '@ana walking through a night market' });

